BEGIN TRANSACTION;

UPDATE Production.ProductInventory
SET Quantity = Quantity - 10
WHERE ProductID = 1 AND LocationID = 1;

UPDATE Production.ProductInventory
SET Quantity = Quantity + 10
WHERE ProductID = 1 AND LocationID = 2;

COMMIT TRANSACTION;
-- Both UPDATEs succeed together, or neither takes effect.

SELECT * FROM my_table VERSION AS OF 5;
SELECT * FROM my_table TIMESTAMP AS OF '2026-01-01';
DESCRIBE HISTORY my_table;

-- Right choice for this scenario: physically stored, real statistics, indexable
CREATE TABLE #ActiveOrders (OrderID INT, CustomerID INT, OrderTotal MONEY);

INSERT INTO #ActiveOrders
SELECT OrderID, CustomerID, OrderTotal FROM Sales.SalesOrderHeader WHERE Status = 'Active';

CREATE INDEX IX_Temp_CustomerID ON #ActiveOrders (CustomerID);
-- Now reused across three statements with an index the optimizer can actually use.

param namespaceName string
param location string = resourceGroup().location

resource eventHubNamespace 'Microsoft.EventHub/namespaces@2022-10-01-preview' = {
  name: namespaceName
  location: location
  sku: {
    name: 'Standard'
    tier: 'Standard'
  }
}

{
  "Comment": "Run a Glue job and notify on success or failure",
  "StartAt": "RunGlueJob",
  "States": {
    "RunGlueJob": {
      "Type": "Task",
      "Resource": "arn:aws:states:::glue:startJobRun.sync",
      "Parameters": {
        "JobName": "daily-orders-etl"
      },
      "Catch": [
        {
          "ErrorEquals": ["States.ALL"],
          "Next": "NotifyFailure"
        }
      ],
      "Next": "NotifySuccess"
    },
    "NotifySuccess": {
      "Type": "Task",
      "Resource": "arn:aws:states:::sns:publish",
      "Parameters": {
        "TopicArn": "arn:aws:sns:us-east-1:123456789012:pipeline-notifications",
        "Message": "Glue job daily-orders-etl succeeded."
      },
      "End": true
    },
    "NotifyFailure": {
      "Type": "Task",
      "Resource": "arn:aws:states:::sns:publish",
      "Parameters": {
        "TopicArn": "arn:aws:sns:us-east-1:123456789012:pipeline-notifications",
        "Message": "Glue job daily-orders-etl failed."
      },
      "End": true
    }
  }
}

-- NON-SARGABLE: forces a full scan even with an index on OrderDate
WHERE YEAR(OrderDate) = 2013;

-- SARGABLE rewrite: the column itself is untouched, index can be used
WHERE OrderDate >= '2013-01-01' AND OrderDate < '2014-01-01';

-- Likely cause: SELECT * defeats the covering index
SELECT * FROM Sales.SalesOrderDetail WHERE ProductID = 712;

-- Fix: name only the columns the covering index actually includes
SELECT SalesOrderID, ProductID, OrderQty, UnitPrice
FROM Sales.SalesOrderDetail WHERE ProductID = 712;

-- BREAKS partition pruning: function wrapped around the partition column
WHERE CAST(order_date AS DATE) = CURRENT_DATE - 1;

-- FIXED: compare the raw partition value against a matching string literal
WHERE order_date = CAST(CURRENT_DATE - INTERVAL '1' DAY AS VARCHAR);
-- or, even more directly, precompute and inline the literal:
WHERE order_date = '2026-01-14';
